const { vec } = NMath;
const { vertices } = await IO.loadMesh("/assets/bunny.obj");
if (vertices.length === 0) throw new Error("The bunny mesh contains no vertices");

// Center and scale the vertices; rotate them so the bunny is upright in the 3D plot.
const points = vertices.map(vertex => vec(...vertex));
const mean = points.reduce((sum, point) => sum.add(point), vec.zero(3)).scale(1 / points.length);
const centered = points.map(point => point.sub(mean));
const scale = Math.max(...centered.flatMap(point => point.components.map(Math.abs)));
if (!Number.isFinite(scale) || scale === 0) throw new Error("The bunny mesh has invalid coordinates");
const all = centered.map(point => {
    const [x, y, z] = point.scale(1 / scale).components;
    return vec(z, x, y);
});

// Sinkhorn is quadratic in the number of points, so use a random subset of the vertices.
const count = Math.min(800, all.length);
const targets = [...all].sort(() => Math.random() - 0.5).slice(0, count);
const bounds = [0, 1, 2].map(axis => [
    Math.min(...all.map(point => point.components[axis])),
    Math.max(...all.map(point => point.components[axis])),
]);
const randomPoint = () => vec(...bounds.map(([min, max]) => min + Math.random() * (max - min)));
const initial = Array.from({ length: count }, randomPoint);

const ot = OptimalTransport.new(
    { points: initial },
    { points: targets },
    { entropy: 0.002 },
).fit();
console.log(`Sinkhorn iterations: ${ot.iterations}, transport cost: ${ot.cost().toFixed(4)}`);

const plot = IO.plotPointCloud(all, { aspect: "equal", radius: 0.008, color: [0.4, 0.4, 0.4] });
const moving = plot.add(initial, { radius: 0.012, color: [1, 0, 0] });
// Invisible points keep a stable view while the samples move.
plot.add([[-1.3, -1.3, -1.3], [1.3, 1.3, 1.3]], { color: [0, 0, 0] });

const showTime = t => {
    moving.update(ot.interpolate(t), { color: [1 - t, t, 0] });
    plot.render();
};

const ui = IO.UI(
    { type: "canvas", value: () => plot },
    {
        type: "slider", value: () => ({
            title: "t:", min: 0, max: 1, step: 0.01, value: 0,
            onChange: showTime,
        })
    },
);
showTime(0);
ui;
